#include "vector-test-shim.h"
static __device__ unsigned long long fg175v_paths,fg175v_features;
template<int N>static __global__ __launch_bounds__(128,1)void fg175v_kernel(const char*Q,const char*K,const char*V,const char*mask,const char*sinks,const int*KVmax,float*dst,float2*meta,float scale,float bias,float m0,float m1,uint32_t nh,float softcap,int ne00,uint3 ne01,int ne02,int ne03,int nb01,int nb02,int nb03,int ne10,int ne11,int ne12,int ne13,int nb11,int nb12,int64_t nb13,int nb21,int nb22,int64_t nb23,int ne31,int ne32,int ne33,int nb31,int nb32,int64_t nb33){extern __shared__ float bytes[];if(blockIdx.x==0&&blockIdx.y==0&&blockIdx.z==0&&threadIdx.x==0&&threadIdx.y==0){atomicOr(&fg175v_paths,N==1?1ULL:2ULL);atomicOr(&fg175v_features,(gridDim.y>1?1ULL:0ULL)|(mask?2ULL:0ULL)|(sinks?4ULL:0ULL)|(KVmax?8ULL:0ULL));}FG175V_VEC((uint64_t)(uintptr_t)Q,(uint64_t)(uintptr_t)K,(uint64_t)(uintptr_t)V,(uint64_t)(uintptr_t)mask,(uint64_t)(uintptr_t)sinks,(uint64_t)(uintptr_t)KVmax,(uint64_t)(uintptr_t)dst,(uint64_t)(uintptr_t)meta,scale,bias,m0,m1,nh,softcap,ne00,ne01.z,ne02,ne03,nb01,nb02,nb03,ne10,ne11,ne12,ne13,nb11,nb12,nb13,nb21,nb22,nb23,ne31,ne32,ne33,nb31,nb32,nb33,N,blockIdx.x,blockIdx.y,blockIdx.z,gridDim.x,gridDim.y,threadIdx.x,threadIdx.y,(uint64_t)(uintptr_t)bytes,1);}
static __global__ void fg175v_combine(const float*parts,const float2*meta,float*dst,int pb){extern __shared__ float smem[];if(blockIdx.x==0&&blockIdx.y==0&&blockIdx.z==0&&threadIdx.x==0)atomicOr(&fg175v_paths,4ULL);FG175V_COMBINE((uint64_t)(uintptr_t)parts,(uint64_t)(uintptr_t)meta,(uint64_t)(uintptr_t)dst,pb,blockIdx.x,blockIdx.y,blockIdx.z,gridDim.x,gridDim.y,threadIdx.x,(uint64_t)(uintptr_t)smem,1);}
template<int N>static void fg175v_test_impl(ggml_backend_cuda_context&ctx,ggml_tensor*dst,int pb,bool original,float*parts,float2*meta,const int*kvmax){const auto*Q=dst->src[0];const auto*K=dst->src[1];const auto*V=dst->src[2];const auto*M=dst->src[3];const auto*S=dst->src[4];float scale,bias,soft;memcpy(&scale,dst->op_params,4);memcpy(&bias,(char*)dst->op_params+4,4);memcpy(&soft,(char*)dst->op_params+8,4);uint32_t nh=1;while(nh*2<=Q->ne[2])nh*=2;const float m0=powf(2,-bias/nh),m1=powf(2,-(bias/2)/nh);dim3 grid((Q->ne[1]+N-1)/N,pb,Q->ne[2]*Q->ne[3]);ggml_cuda_kernel_launch_params lp(grid,dim3(32,4),original?0:4608,ctx.stream());float*out=pb>1?parts:(float*)dst->data;
#define FG175V_TEST_ARGS (const char*)Q->data,(const char*)K->data,(const char*)V->data,M?(const char*)M->data:nullptr,S?(const char*)S->data:nullptr,kvmax,out,meta,scale,bias,m0,m1,nh,soft,(int)Q->ne[0],init_fastdiv_values(Q->ne[1]),(int)Q->ne[2],(int)Q->ne[3],(int)Q->nb[1],(int)Q->nb[2],(int)Q->nb[3],(int)K->ne[0],(int)K->ne[1],(int)K->ne[2],(int)K->ne[3],(int)K->nb[1],(int)K->nb[2],(int64_t)K->nb[3],(int)V->nb[1],(int)V->nb[2],(int64_t)V->nb[3],M?(int)M->ne[1]:1,M?(int)M->ne[2]:1,M?(int)M->ne[3]:1,M?(int)M->nb[1]:0,M?(int)M->nb[2]:0,M?(int64_t)M->nb[3]:0
if(original)ggml_cuda_kernel_launch(fg175v_native_flash_attn_ext_vec<256,N,GGML_TYPE_Q4_0,GGML_TYPE_Q4_0,false>,lp,FG175V_TEST_ARGS);else ggml_cuda_kernel_launch(fg175v_kernel<N>,lp,FG175V_TEST_ARGS);
#undef FG175V_TEST_ARGS
if(pb>1){if(original)fg175v_native_flash_attn_combine_results<256><<<dim3(Q->ne[1],Q->ne[2],Q->ne[3]),256,pb*sizeof(float2),ctx.stream()>>>(parts,meta,(float*)dst->data,pb);else fg175v_combine<<<dim3(Q->ne[1],Q->ne[2],Q->ne[3]),256,pb*sizeof(float2),ctx.stream()>>>(parts,meta,(float*)dst->data,pb);}}
void fg175v_test_run(ggml_backend_cuda_context&ctx,ggml_tensor*dst,int ncols,int pb,bool original,float*parts,float2*meta,const int*kvmax){GGML_ASSERT(ncols==1||ncols==2);if(ncols==1)fg175v_test_impl<1>(ctx,dst,pb,original,parts,meta,kvmax);else fg175v_test_impl<2>(ctx,dst,pb,original,parts,meta,kvmax);}
extern "C" int fg175v_test_witness(uint64_t*out){auto s=cudaMemcpyFromSymbol(out,fg175v_paths,sizeof(fg175v_paths));if(s==cudaSuccess)s=cudaMemcpyFromSymbol(out+1,fg175v_features,sizeof(fg175v_features));return(int)s;}
